import assert from "node:assert/strict";
import { compareReports, validateReport } from "./local-value-compare-lib.mjs";

// expected is generated by the current Rust binary, not supplied by an input report.
export function auditOrder(inputs, expected) {
  const comparison = compareReports(inputs);
  const reports = inputs.map(validateReport);
  assert.equal(expected[0].quality_version, "rss-order-v1");
  const labels = [...expected[0].items].sort();
  for (const manifest of expected) {
    assert.deepEqual([...manifest.items].sort(), labels);
    assert.deepEqual(manifest.checks, expected[0].checks);
  }
  for (const report of reports) {
    assert.equal(report.run_scope, "full_corpus");
    assert.deepEqual(report.manifests, expected, "not the current frozen order suite");
  }
  const ordered = [...reports].sort((a, b) => Date.parse(a.started_at) - Date.parse(b.started_at));
  for (let i = 1; i < ordered.length; i++) {
    assert.ok(Date.parse(ordered[i].started_at) > Date.parse(ordered[i - 1].started_at));
    assert.ok(Date.parse(ordered[i].started_at) >= Date.parse(ordered[i - 1].ended_at));
  }
  const rounds = reports.map((report, index) => {
    const items = labels.map(item => {
      const values = report.results.map(r => r.scores[item]);
      return { item, completed_permutations: values.length, expected_permutations: expected.length,
        distinct_scores: [...new Set(values)], observed_variation: new Set(values).size > 1 };
    });
    return { round: index + 1, complete: report.complete,
      order_invariant: items.some(item => item.observed_variation) ? false : report.complete ? true : null, items };
  });
  return { schema: "rss-order-audit-v1", synthetic_only: true,
    execution_profile: expected[0].execution_profile, runtime: reports[0].runtime,
    order_gate_passed: comparison.all_passed && comparison.repeated_identically && rounds.every(r => r.order_invariant === true),
    comparison, rounds, configuration_changed: false, real_material_quality_verified: false };
}
